//! Compare scripted two-lookup composition with retained native rows.
use spore_core::cell_provider_two_lookup_join_v1::{project,Inner,Outer,Route};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let p=std::env::args().nth(1).expect("native stdout");let b=std::fs::read(p).unwrap();assert_eq!(b.len(),320);for i in 0..10{let k=i%5;let cw=if i>=5{0x37f}else{0x27f};let input=match k{0=>Outer::Miss{post_lookup_slot:Some(2)},1=>Outer::Found{post_inner_lookup_slot:Some(2),inner:Inner::Hit{candidate:3,post_callback_slot:Some(3)}},2=>Outer::Found{post_inner_lookup_slot:Some(2),inner:Inner::Hit{candidate:3,post_callback_slot:Some(4)}},3=>Outer::Found{post_inner_lookup_slot:Some(2),inner:Inner::Miss{factory_result:None}},_=>Outer::Found{post_inner_lookup_slot:Some(2),inner:Inner::Miss{factory_result:Some(1)}}};let x=project(input,0x12345678,cw,0x1f80,true).unwrap();let r=&b[i*32..(i+1)*32];assert_eq!(w(r,0),x.slot.unwrap_or(0));assert_eq!(w(r,4),u32::from(x.lookup_calls));let factory=u32::from(x.route==Route::Factory);assert_eq!(w(r,8),factory);assert_eq!(w(r,12),factory);assert_eq!(w(r,16),match x.route{Route::OuterMiss=>1,Route::InnerHit=>2,Route::Factory=>0});let fp=w(r,20);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(r,24)&!0x3f,0x1f80);assert_eq!(w(r,28),i as u32);}println!("matched 10 retained two-lookup rows; callbacks and maps scripted");}
